<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowRight, Check, InfoFilled } from '@element-plus/icons-vue'
import { api } from '@/api/client'
interface Transfer{id:number;currentRoom:string;preferredArea:string;reason:string;status:string;createdAt:string;targetRoom?:string;targetBed?:string;remark?:string;handledAt?:string;confirmedAt?:string}
const list=ref<Transfer[]>([]),submitting=ref(false),confirming=ref(false)
const form=reactive({preferredArea:'松园片区',reason:''})
const activeRequest=computed(()=>list.value.find(item=>['审核中','待搬迁'].includes(item.status)))
async function load(){list.value=await api.get<Transfer[]>('/api/student/transfers')}
async function submit(){if(activeRequest.value)return ElMessage.warning('你已有一条正在办理的调宿申请');if(form.reason.trim().length<10)return ElMessage.warning('请至少填写 10 个字的调宿原因');submitting.value=true;try{await api.post('/api/student/transfers',form);ElMessage.success('调宿申请已提交');form.reason='';await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'提交失败')}finally{submitting.value=false}}
async function confirmMove(item:Transfer){try{await ElMessageBox.confirm(`请确认你已搬入 ${item.targetRoom} ${item.targetBed}，确认后本次调宿流程将完成。`,'确认搬迁',{confirmButtonText:'已完成搬迁',cancelButtonText:'暂不确认',type:'success'});confirming.value=true;await api.patch(`/api/student/transfers/${item.id}/confirm`);ElMessage.success('搬迁确认成功');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'确认失败')}finally{confirming.value=false}}
function step(item:Transfer){return item.status==='审核中'?1:item.status==='待搬迁'?3:item.status==='已完成'?4:1}
onMounted(load)
</script>
<template><div><div class="student-page-head"><span>ROOM TRANSFER</span><h1>调宿申请</h1><p>提交申请、查看宿管安排，并在搬迁完成后在线确认。</p></div><section v-if="activeRequest" class="active-process"><div><span>当前申请</span><h2>{{activeRequest.status}}</h2><p v-if="activeRequest.status==='审核中'">宿管老师正在审核你的申请，请耐心等待。</p><p v-else>宿管已安排 {{activeRequest.targetRoom}} {{activeRequest.targetBed}}，请完成搬迁后确认。</p></div><button v-if="activeRequest.status==='待搬迁'" :disabled="confirming" @click="confirmMove(activeRequest)"><el-icon><Check/></el-icon>确认已搬迁</button></section><section class="transfer-grid"><article class="student-card form-card"><header><h2>填写申请</h2><span>当前宿舍：{{list[0]?.targetRoom||list[0]?.currentRoom||'松园1号楼 302'}}</span></header><div class="form-body"><label><span>意向区域</span><select v-model="form.preferredArea"><option>松园片区</option><option>竹园片区</option><option>无特殊要求</option></select></label><label><span>调宿原因</span><textarea v-model="form.reason" maxlength="300" placeholder="请详细说明申请调宿的原因（至少 10 个字）"/><small>{{form.reason.length}} / 300</small></label><div class="notice"><el-icon><InfoFilled/></el-icon><p>同一时间只能办理一条申请，涉及健康原因时可能需要补充证明。</p></div><button class="submit" :disabled="submitting||!!activeRequest" @click="submit">{{activeRequest?'已有申请正在办理':submitting?'正在提交...':'提交调宿申请'}} <el-icon><ArrowRight/></el-icon></button></div></article><aside class="student-card process-card"><header><h2>办理流程</h2></header><ol><li v-for="(label,index) in ['提交申请','宿管审核','搬迁入住','确认完成']" :key="label" :class="{active:(activeRequest?step(activeRequest):0)>=index+1}"><i>{{index+1}}</i><div><strong>{{label}}</strong><span>{{['填写意向与调宿原因','核对原因并安排床位','按通知迁入新宿舍','在线确认完成流程'][index]}}</span></div></li></ol></aside></section><section v-if="list.length" class="student-card history"><header><h2>申请记录</h2></header><article v-for="item in list" :key="item.id"><div><span>{{item.createdAt}}</span><strong>{{item.currentRoom}} → {{item.targetRoom||item.preferredArea}}</strong><p>{{item.reason}}</p><small v-if="item.remark">宿管说明：{{item.remark}}</small></div><b :class="item.status">{{item.status}}</b><button v-if="item.status==='待搬迁'" @click="confirmMove(item)">确认搬迁</button></article></section></div></template>
<style scoped>.student-page-head{margin-bottom:18px}.student-page-head>span{color:#198075;font-size:8px;letter-spacing:1.4px}.student-page-head h1{margin:5px 0;font-size:25px}.student-page-head p{margin:0;color:#82908c;font-size:11px}.active-process{margin-bottom:16px;padding:18px 21px;border-radius:13px;display:flex;align-items:center;justify-content:space-between;color:white;background:linear-gradient(120deg,#166f67,#32988b)}.active-process span{color:#b7ded8;font-size:8px}.active-process h2{margin:4px 0;font-size:17px}.active-process p{margin:0;color:#c4e2dd;font-size:9px}.active-process button{height:36px;padding:0 13px;border:1px solid rgba(255,255,255,.4);border-radius:7px;display:flex;align-items:center;gap:6px;color:white;background:rgba(255,255,255,.12);font-size:10px}.transfer-grid{display:grid;grid-template-columns:1.5fr .75fr;gap:17px}.student-card{border:1px solid #e1e7e4;border-radius:14px;background:white}.student-card header{height:61px;padding:0 20px;border-bottom:1px solid #edf0ef;display:flex;align-items:center;justify-content:space-between}.student-card h2{margin:0;font-size:14px}.student-card header span{color:#7e8b87;font-size:9px}.form-body{padding:21px}.form-body label{position:relative;margin-bottom:19px;display:grid;gap:8px}.form-body label>span{font-size:10px;font-weight:600}.form-body select,.form-body textarea{width:100%;border:1px solid #dfe5e3;border-radius:8px;outline:0;color:#34423e;background:white;font-size:10px}.form-body select{height:40px;padding:0 11px}.form-body textarea{height:120px;padding:11px;resize:vertical;line-height:1.7}.form-body label small{position:absolute;right:9px;bottom:8px;color:#a0aaa7;font-size:8px}.notice{margin-bottom:18px;padding:11px;border-radius:8px;display:flex;gap:8px;color:#897248;background:#fff8e9}.notice p{margin:0;font-size:9px;line-height:1.7}.submit{height:41px;padding:0 16px;border:0;border-radius:8px;display:flex;align-items:center;justify-content:center;gap:6px;color:white;background:#11796f;font-size:11px}.submit:disabled{opacity:.55}.process-card ol{margin:0;padding:21px;list-style:none}.process-card li{min-height:63px;position:relative;display:flex;gap:11px}.process-card li:after{content:'';position:absolute;left:13px;top:29px;width:1px;height:31px;background:#dfe6e4}.process-card li:last-child:after{display:none}.process-card li>i{width:27px;height:27px;z-index:1;border:1px solid #d7dfdd;border-radius:50%;display:grid;place-items:center;color:#889592;background:white;font-style:normal;font-size:9px}.process-card li.active>i{border-color:#158276;color:white;background:#158276}.process-card li>div{display:grid;height:max-content;gap:4px}.process-card strong{font-size:10px}.process-card li span{color:#929d99;font-size:8px}.history{margin-top:17px}.history>article{padding:15px 20px;border-top:1px solid #edf0ef;display:flex;align-items:center;gap:15px}.history article>div{min-width:0;display:grid;gap:4px;flex:1}.history article span,.history article p,.history article small{margin:0;color:#84918d;font-size:9px}.history article strong{font-size:10px}.history article>b{color:#b17527;font-size:9px}.history article>b.已完成{color:#19796e}.history article>b.已驳回{color:#b85f57}.history article button{padding:6px 9px;border:1px solid #bcded8;border-radius:6px;color:#14776c;background:#f0f8f6;font-size:9px}@media(max-width:700px){.transfer-grid{grid-template-columns:1fr}.active-process{align-items:flex-start;gap:12px;flex-direction:column}.history>article{align-items:flex-start;flex-direction:column}}</style>
